@startuml

class Person {
  + personID : int
  + phoneNumber : string
  + keywords : string[]
}

class Institution {
  + institutionCode : string
}

class Article {
  + DOI : string
  + title : string
}

class PeerReviewedPaper extends Article {
  + citationCount : int
}

class TechnicalReport extends Article {}

class AuthorPosition {
  + position : string
}

class Publisher {
  + name : string
}

class Journal {
  + name : string
  + impactFactor : float
}

Person "1" -- "0..*" Institution : works for
Person "1" -- "0..*" Article : authors
Person "0..1" -- "0..*" PeerReviewedPaper : reviews

Article "1" -- "*" AuthorPosition
Person "1" -- "*" AuthorPosition : in position

Institution "1" -- "0..*" TechnicalReport : publishes
Publisher "1" -- "0..*" Journal : publishes
Institution "0..*" -- "0..*" Journal : subscribes
Journal "1" -- "0..*" PeerReviewedPaper : publishes

@enduml

